<?php
namespace App\Http\Controllers;
use App\Models\ContentItem; use App\Models\Inquiry; use App\Models\Setting; use Illuminate\Http\Request;
class PublicController extends Controller {
 private function items($type,$published=true){ $q=ContentItem::type($type)->orderBy('sort_order')->orderBy('id'); if($published)$q->published(); return $q->get(); }
 private function common(){ return ['settings'=>Setting::pluck('value','key')]; }
 public function home(){return view('public.home',array_merge($this->common(),['hero'=>$this->items('hero')->first(),'achievements'=>$this->items('achievements'),'services'=>$this->items('services'),'whyChoose'=>$this->items('why-choose'),'projects'=>$this->items('projects'),'properties'=>$this->items('properties')->take(6),'process'=>$this->items('process'),'beforeAfter'=>$this->items('before-after'),'testimonials'=>$this->items('testimonials'),'team'=>$this->items('team')->take(4),'partners'=>$this->items('partners'),'news'=>$this->items('news')->take(3),'faqs'=>$this->items('faqs'),'consultation'=>$this->items('consultation')->first(),'social'=>$this->items('social')]));}
 public function about(){return view('public.about',array_merge($this->common(),['achievements'=>$this->items('achievements'),'whyChoose'=>$this->items('why-choose'),'team'=>$this->items('team'),'testimonials'=>$this->items('testimonials'),'partners'=>$this->items('partners')]));}
 public function services(){return view('public.services',array_merge($this->common(),['services'=>$this->items('services'),'whyChoose'=>$this->items('why-choose'),'process'=>$this->items('process'),'gallery'=>$this->items('gallery'),'beforeAfter'=>$this->items('before-after'),'testimonials'=>$this->items('testimonials'),'faqs'=>$this->items('faqs')]));}
 public function service($slug){$item=ContentItem::type('services')->where('slug',$slug)->firstOrFail();return view('public.service-detail',array_merge($this->common(),['item'=>$item,'process'=>$this->items('process')]));}
 public function projects(Request $r){$q=ContentItem::type('projects')->published(); if($r->category)$q->where('data->category',$r->category); if($r->status)$q->where('status',$r->status); $featured=ContentItem::type('projects')->published()->where('slug','zaman-villas')->first(); return view('public.projects',array_merge($this->common(),['projects'=>$q->orderBy('sort_order')->get(),'featured'=>$featured,'achievements'=>$this->items('achievements'),'beforeAfter'=>$this->items('before-after'),'testimonials'=>$this->items('testimonials')]));}
 public function project($slug){$item=ContentItem::type('projects')->where('slug',$slug)->firstOrFail();$related=ContentItem::type('projects')->published()->whereKeyNot($item->id)->take(3)->get();$gallery=$this->items('gallery');$properties=ContentItem::type('properties')->published()->where('data->project',$item->title)->orderBy('sort_order')->get();return view('public.project-detail',array_merge($this->common(),compact('item','related','gallery','properties')));}
 public function properties(Request $r){$q=ContentItem::type('properties')->published(); foreach(['property_type','location','property_status','area','beds'] as $f) if($r->$f)$q->where("data->$f",'like','%'.$r->$f.'%'); return view('public.properties',array_merge($this->common(),['properties'=>$q->orderBy('sort_order')->paginate(12)->withQueryString()]));}
 public function property($slug){$item=ContentItem::type('properties')->where('slug',$slug)->firstOrFail();$related=ContentItem::type('properties')->published()->whereKeyNot($item->id)->take(3)->get();return view('public.property-detail',array_merge($this->common(),compact('item','related')));}
 public function gallery(){return view('public.gallery',array_merge($this->common(),['gallery'=>$this->items('gallery'),'beforeAfter'=>$this->items('before-after')]));}
 public function team(){return view('public.team',array_merge($this->common(),['team'=>$this->items('team')]));}
 public function achievements(){return view('public.achievements',array_merge($this->common(),['achievements'=>$this->items('achievements'),'partners'=>$this->items('partners')]));}
 public function news(){return view('public.news',array_merge($this->common(),['news'=>$this->items('news')]));}
 public function newsDetail($slug){$item=ContentItem::type('news')->where('slug',$slug)->firstOrFail();return view('public.news-detail',array_merge($this->common(),compact('item')));}
 public function contact(){return view('public.contact',array_merge($this->common(),['faqs'=>$this->items('faqs'),'social'=>$this->items('social')]));}
 public function locations(){return view('public.locations',$this->common());}
 public function inquiry(Request $request){$data=$request->validate(['type'=>'required|string|max:100','name'=>'required|string|max:150','email'=>'nullable|email|max:190','phone'=>'nullable|string|max:50','subject'=>'nullable|string|max:190','reference'=>'nullable|string|max:190','message'=>'nullable|string|max:5000']);Inquiry::create($data);return back()->with('success','Thank you. Your enquiry has been received.');}
}
